package dev.pocketengine.features.assistant.notifications;
import org.json.*;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class TaskNotificationStateTest {
 private static JSONObject task()throws Exception{return new JSONObject().put("id",UUID.randomUUID().toString()).put("runId",UUID.randomUUID().toString()).put("coordinatorEpoch",2).put("kind","assistant").put("executionMode","capabilities").put("actorId","owner").put("spaceId","private").put("status","needs_confirmation").put("conversationId",UUID.randomUUID().toString()).put("goal","LOCKSCREEN-MUST-NOT-SEE-THIS").put("summary","SECRET-ACTUAL-MODEL-BODY");}
 @Test public void resultLocatorContainsNoGoalModelBodyOrExecutionAuthority()throws Exception{JSONObject notice=TaskNotificationState.candidate(task());assertEquals("result",notice.getString("anchor"));assertFalse(notice.getBoolean("executionAuthorized"));assertFalse(notice.getBoolean("deliveryConfirmed"));assertFalse(notice.toString().contains("LOCKSCREEN"));assertFalse(notice.toString().contains("SECRET"));assertTrue(notice.getString("token").matches("[a-f0-9]{64}"));}
 @Test public void sameActualTupleIsStableButReplacementRunOrDecisionInvalidatesToken()throws Exception{JSONObject t=task(),before=TaskNotificationState.candidate(t);assertEquals(before.getString("token"),TaskNotificationState.candidate(t).getString("token"));t.put("summary","ordinary stream text changed");assertEquals(before.getString("token"),TaskNotificationState.candidate(t).getString("token"));t.put("status","reconciling");assertNotEquals(before.getString("token"),TaskNotificationState.candidate(t).getString("token"));t.put("status","needs_confirmation").put("runId",UUID.randomUUID().toString());assertNotEquals(before.getString("token"),TaskNotificationState.candidate(t).getString("token"));}
 @Test public void waitingOrUnknownIsNeverPresentedAsCompletion()throws Exception{JSONObject t=task().put("status","reconciling");assertEquals("reconciliation",TaskNotificationState.candidate(t).getString("anchor"));assertFalse(TaskNotificationState.title("reconciling").contains("完成"));t.put("status","awaiting_user");assertEquals("decision",TaskNotificationState.candidate(t).getString("anchor"));assertFalse(TaskNotificationState.title("awaiting_user").contains("完成"));}
 @Test public void teamsChannelsLearningAndAccountingAreNotPrivateAssistantNotices()throws Exception{for(String kind:List.of("phone","teams","inference"))assertNull(TaskNotificationState.candidate(task().put("kind",kind)));for(String origin:List.of("channel","group","automation","team_local_assignment"))assertNull(TaskNotificationState.candidate(task().put("origin",new JSONObject().put("kind",origin))));assertNull(TaskNotificationState.candidate(task().put("sourceLearningJob",new JSONObject())));}
 @Test public void runningPausedAndUnboundRecordsDoNotPretendResultOrOwnerDecision()throws Exception{for(String status:List.of("preparing","running","model","paused","stopping","recording"))assertNull(TaskNotificationState.candidate(task().put("status",status)));assertNull(TaskNotificationState.candidate(task().put("runId","")));assertNull(TaskNotificationState.candidate(task().put("coordinatorEpoch",0)));assertNull(TaskNotificationState.candidate(task().put("spaceId","group")));}
 @Test public void privateReviewedVoiceOriginalTaskKeepsItsOriginalLocator()throws Exception{JSONObject t=task().put("origin",new JSONObject().put("kind","owner_reviewed_realtime")),notice=TaskNotificationState.candidate(t);assertEquals(t.getString("id"),notice.getString("taskId"));assertEquals(t.getString("runId"),notice.getString("runId"));assertEquals(t.getInt("coordinatorEpoch"),notice.getInt("epoch"));}
}
